<?php require "includes/db.php";$pageTitle="Contact | Artisan Brew Co.";$sent=false;if($_SERVER['REQUEST_METHOD']==='POST'){$s=$conn->prepare("INSERT INTO contacts(name,email,message) VALUES(?,?,?)");$s->bind_param("sss",$_POST['name'],$_POST['email'],$_POST['message']);$s->execute();$sent=true;}require "includes/header.php";?><section class="form-page"><div class="form-card wide"><p class="eyebrow">VISIT & CONNECT</p><h1>Contact <em>Us.</em></h1><?php if($sent):?><div class="success-msg">Thanks! Your message has been received.</div><?php endif;?><form method="post"><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Message<textarea name="message" rows="6" required></textarea></label><button class="btn dark">Send Message</button></form></div></section><?php require "includes/footer.php";?>